#include "RuntimeClosedLoopFeedbackStage.h"
namespace dnxr { const char* RuntimeClosedLoopFeedbackStage::name(){return "closed_loop_feedback";} RuntimePipelineFrame RuntimeClosedLoopFeedbackStage::execute(RuntimePipelineFrame frame,const ClosedLoopNeuralFeedbackReader& reader){ frame.closedLoopFeedback=reader.read(frame.feedbackChipFrame.sequenceId ? frame.feedbackChipFrame : frame.chipFrame,frame.stimulusCommand); if(!frame.closedLoopFeedback.safetyVerified){ frame.stimulusStatus=RuntimeStageStatus::degraded("closed_loop_feedback_not_verified"); } return frame; } }
